//! Actual immutable target definitions/maps; independently specified ordinary Rune altar bindings.
use gielinor_cache::{game::{Definitions,GameCache},symbols,definitions::{ItemType,StatType},locations::LocationType};use gielinor_server::content::ordinary_rune_altars;use std::{collections::{BTreeMap,BTreeSet},path::Path};
fn copy(d:&Definitions)->Definitions{Definitions{inventories:BTreeMap::new(),locations:d.locations.clone(),npcs:BTreeMap::new(),items:d.items.clone(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:d.stats.clone()}}
const ORDINARY:[i32;8]=[1436,7936,556,558,555,557,554,559];const HELD:[i32;6]=[24704,26879,28593,28595,28597,28599];const WORN:[i32;27]=[26822,26824,26826,26828,26830,26832,26834,26836,26838,26840,26842,26844,26846,26848,26850,26852,26854,26856,26858,26860,26862,26864,26866,26868,26870,26872,26874];
#[test]fn actual_forty_one_items_six_altars_stat_effects_and_three_hundred_fifty_five_binding_refusals(){let dir=std::env::var("PG_SYMBOLS").unwrap();let names=|name|symbols::load(&[Path::new(&dir)],name,None).unwrap();let obj=names("obj");let loc=names("loc");let seq=names("seq");let spot=names("spotanim");let stat=names("stat");let path=std::env::var("PG_GAME_CACHE").unwrap();let mut cache=GameCache::open(Path::new(&path),0xff_ffff).unwrap();let item_bytes=cache.files(2,10,None).unwrap().unwrap();let loc_bytes=cache.files(2,6,None).unwrap().unwrap();let stat_bytes=cache.files(2,200,None).unwrap().unwrap();let mut d=Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:BTreeMap::new(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:BTreeMap::new()};for id in ORDINARY.into_iter().chain(HELD).chain(WORN){d.items.insert(id as u32,ItemType::decode(&item_bytes[&(id as u32)]).unwrap());}for id in 34760..=34765{d.locations.insert(id,LocationType::decode(&loc_bytes[&id]).unwrap());}d.stats.insert(20,StatType::decode(&stat_bytes[&20]).unwrap());let c=ordinary_rune_altars(&obj,&loc,&seq,&spot,&stat,&d).unwrap();assert_eq!((d.items.len(),c.altars.len(),c.animation,c.spot),(41,6,791,186));assert_eq!(c.blocked_held,HELD.into());assert_eq!(c.blocked_worn,WORN.into());for(i,(output,level,xp,interval))in[(556,1,50,11),(558,2,55,14),(555,5,60,19),(557,9,65,26),(554,14,70,35),(559,20,75,46)].into_iter().enumerate(){let r=c.altars[&(34760+i as u32)];assert_eq!((r.output,r.level,r.xp_tenths,r.interval),(output,level,xp,interval));}let mut n=0;
for id in ORDINARY{for case in 0..10{let mut q=copy(&d);let mut o=obj.clone();match case{0=>{q.items.remove(&(id as u32));},1=>q.items.get_mut(&(id as u32)).unwrap().name="Independent wrong name".into(),2=>q.items.get_mut(&(id as u32)).unwrap().members=true,3=>{let v=q.items.get_mut(&(id as u32)).unwrap();v.stackable=!v.stackable;},4=>q.items.get_mut(&(id as u32)).unwrap().dummy=1,5=>q.items.get_mut(&(id as u32)).unwrap().cert.template=799,6=>q.items.get_mut(&(id as u32)).unwrap().placeholder.template=14401,7=>q.items.get_mut(&(id as u32)).unwrap().transform.template=1,8=>o.retain(|_,v|*v!=id),_=>{for v in o.values_mut(){if *v==id{*v=id+100000;}}}}assert!(ordinary_rune_altars(&o,&loc,&seq,&spot,&stat,&q).is_err(),"item{id} case{case}");n+=1;}}
for id in HELD.into_iter().chain(WORN){for case in 0..6{let mut q=copy(&d);let mut o=obj.clone();match case{0=>{q.items.remove(&(id as u32));},1=>q.items.get_mut(&(id as u32)).unwrap().dummy=1,2=>q.items.get_mut(&(id as u32)).unwrap().cert.template=799,3=>q.items.get_mut(&(id as u32)).unwrap().placeholder.template=14401,4=>q.items.get_mut(&(id as u32)).unwrap().transform.template=1,_=>o.retain(|_,v|*v!=id)}assert!(ordinary_rune_altars(&o,&loc,&seq,&spot,&stat,&q).is_err(),"guard{id} case{case}");n+=1;}}
for id in 34760..=34765{for case in 0..11{let mut q=copy(&d);let mut l=loc.clone();match case{0=>{q.locations.remove(&id);},1=>q.locations.get_mut(&id).unwrap().name="Independent wrong altar".into(),2=>q.locations.get_mut(&id).unwrap().collision.width=1,3=>q.locations.get_mut(&id).unwrap().collision.length=1,4=>q.locations.get_mut(&id).unwrap().ops[0]=None,5=>q.locations.get_mut(&id).unwrap().ops[0]=Some("Use".into()),6=>q.locations.get_mut(&id).unwrap().multi=vec![1],7=>q.locations.get_mut(&id).unwrap().multi_varbit=1,8=>q.locations.get_mut(&id).unwrap().multi_varp=1,9=>q.locations.get_mut(&id).unwrap().multi_default=1,_=>l.retain(|_,v|*v!=id as i32)}assert!(ordinary_rune_altars(&obj,&l,&seq,&spot,&stat,&q).is_err(),"altar{id} case{case}");n+=1;}}
for case in 0..11{let mut q=copy(&d);let mut s=stat.clone();let mut a=seq.clone();let mut b=spot.clone();match case{0=>{s.remove("runecrafting");},1=>{s.insert("runecrafting".into(),21);},2=>{q.stats.remove(&20);},3=>q.stats.get_mut(&20).unwrap().name="Wrong".into(),4=>q.stats.get_mut(&20).unwrap().unreleased=true,5=>q.stats.get_mut(&20).unwrap().min_level=0,6=>q.stats.get_mut(&20).unwrap().max_level=98,7=>{a.remove("human_runecraft");},8=>{a.insert("human_runecraft".into(),792);},9=>{b.remove("runecrafting");},_=>{b.insert("runecrafting".into(),187);}}assert!(ordinary_rune_altars(&obj,&loc,&a,&b,&s,&q).is_err(),"skill/effect case{case}");n+=1;}assert_eq!(n,355);println!("PG_RUNE_BINDINGS actual_items41 altars6 stat20 sequence791 spot186 refusals={n}");}
#[test]fn independently_observe_actual_altar_interior_map_placements(){let path=std::env::var("PG_GAME_CACHE").unwrap();let mut cache=GameCache::open(Path::new(&path),0xff_ffff).unwrap();let mut found=BTreeSet::new();for x in 38u16..=45{for z in 74u16..=76{if let Some(square)=cache.map_square((x<<8)|z).unwrap(){for l in square.locations{if(34760..=34765).contains(&l.id){println!("PG_RUNE_ALTAR_PLACEMENT id={} x={} z={} plane={} shape={} angle={}",l.id,x as u32*64+l.x as u32,z as u32*64+l.z as u32,l.level,l.shape,l.angle);found.insert(l.id);}}}}}assert_eq!(found,(34760..=34765).collect());println!("PG_RUNE_ALTAR_MAPPED all6 independently decoded actual interiors");}
